function caseMarkup(html){return html.replace(/<h4>(.*?)<\/h4>([\s\S]*?)(?=<h4>|$)/g,(_,title,body)=>`<details class="case"><summary>${title}</summary><div class="case-content">${body}</div></details>`);}
const icons=['<path d="m8 8-4 4 4 4m8-8 4 4-4 4m-3-10-2 20"/>','<rect x="5" y="5" width="14" height="14" rx="3"/><path d="M9 1v4m6-4v4M9 19v4m6-4v4M1 9h4m-4 6h4m14-6h4m-4 6h4"/>','<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 13h18"/>','<path d="m2 9 10-6 10 6-10 6L2 9m4 3v6c4 4 8 4 12 0v-6"/>','<rect x="3" y="4" width="18" height="14" rx="2"/><path d="M8 22h8m-4-4v4m-4-10 3 3 5-5"/>'];
icons.splice(2,0,'<path d="M4 7h16v13H4zM8 7V3h8v4M8 12h8M8 16h5"/>');
let lang=location.pathname.startsWith('/en')?'en':'zh';
function render(l){lang=l;document.documentElement.lang=l==='zh'?'zh-Hant':'en';document.getElementById('name').innerHTML=l==='zh'?'吳銘嘉<span>Thai Wu</span>':'Thai Wu<span>Ming Chia Wu</span>';document.getElementById('tagline').textContent=l==='zh'?'後端工程與 AI 系統架構':'Backend Engineering & AI Systems';document.getElementById('intro').textContent=l==='zh'?'以 Go、TypeScript 與 Node.js 建置即時遊戲平台、分散式服務與錢包系統。從團隊建立到系統架構，再到 AI 多代理協作，串連技術設計與工程交付。':'Backend engineer and technical leader building real-time game platforms, distributed services, and wallet systems with Go, TypeScript, and Node.js. Connecting system architecture, team leadership, and AI-assisted development.';document.getElementById('nav').innerHTML=CONTENT[l].map((s,i)=>`<a href="#s${i}">${s.title}</a>`).join('');document.getElementById('content').innerHTML=CONTENT[l].map((s,i)=>`<section id="s${i}" class="section"><div class="section-label"><span class="number">0${i+1}</span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">${icons[i]||icons[0]}</svg><h2>${s.title}</h2></div><div class="body">${caseMarkup(s.body)}</div></section>`).join('');document.getElementById('note').textContent=l==='zh'?'資料說明｜內容依履歷與專案紀錄整理，更新於 2026/11/03。原履歷的目前任職狀態、嘉碼任期及公司與科系正式英文名稱仍待確認；專案統計未獨立重新驗證。':'Source note · Updated November 3, 2026. Current employment status, the Gama tenure, and official English company and department names remain to be confirmed. Project statistics have not been independently reverified.';['zh','en'].forEach(k=>document.getElementById(k).setAttribute('aria-pressed',String(k===l)));}
render(lang);
let printStates=[];
addEventListener('beforeprint',()=>{printStates=[...document.querySelectorAll('.case')].map(d=>d.open);document.querySelectorAll('.case').forEach(d=>d.open=true)});
addEventListener('afterprint',()=>document.querySelectorAll('.case').forEach((d,i)=>d.open=printStates[i]||false));
document.getElementById('print').onclick=()=>window.print();
const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){document.querySelectorAll('#nav a').forEach(a=>a.toggleAttribute('aria-current',a.hash==='#'+entry.target.id));}}},{rootMargin:'-15% 0px -65% 0px'});
document.querySelectorAll('.section').forEach(s=>observer.observe(s));

